                border_cells = set()
                for rr in range(r1, r2+1):
                    for cc in range(c1, c2+1):
                        if rr == r1 or rr == r2 or cc == c1 or cc == c2:
                            border_cells.add((rr, cc))

                colors_in_border = set()
                interior_cells = set()

                for rr, cc in border_cells:
                    colors_in_border.add(grid[rr][cc])

                for rr in range(r1+1, r2):
                    for cc in range(c1+1, c2):
                        interior_cells.add((rr, cc))

                if colors_in_border != {1} and len(colors_in_border) == 1:
                    color = list(colors_in_border)[0]
                    hollows.append({
                        'size': size,
                        'top_left': (r1, c1),
                        'color': color,
                        'border_uniform': True,
                        'interior_empty': all(grid[rr][cc] == 1 for rr, cc in interior_cells),
                        'interior_size': len(interior_cells)
