# THE KEY INSIGHT: Hollow frames must have INTERIOR that is NOT the same color as border
def is_hollow_rectangular_frame(grid, region):
    """Check if a connected region forms a COMPLETE HOLLOW RECTANGULAR FRAME"""
    min_r = min(x[0] for x in region)
    max_r = max(x[0] for x in region)
    min_c = min(x[1] for x in region)
    max_c = max(x[1] for x in region)

    # Has interior space? (minimum size for hollow frame is 3x3)
    if max_r <= min_r + 1 or max_c <= min_c + 1:
        return False

    # Get color from first cell
    color = grid[min_r][min_c]

    # Check ALL border cells are present and are the correct color
    border_cells = []
    interior_cells = []

    for r in range(min_r, max_r+1):
        for c in range(min_c, max_c+1):
            if r == min_r or r == max_r or c == min_c or c == max_c:
                border_cells.append((r,c))
            else:
                interior_cells.append((r,c))

    # Verify all borders present with correct color
    for r, c in border_cells:
        if grid[r][c] != color:
            return False

    # CRITICAL CHECK: If there's an interior, its color must be DIFFERENT from border
    if interior_cells:
        for r, c in interior_cells:
            if grid[r][c] == color:
                # Interior same color as border = SOLID, not hollow
                return False

    return True

