def get_components(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    def bfs(r, c, color):
        visited.add((r,c))
        region = [(r,c)]
        queue = [(r,c)]
        while queue:
            rr, cc = queue.pop(0)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = rr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr,nc) not in visited and grid[nr][nc] == color:
                        visited.add((nr,nc))
                        region.append((nr,nc))
                        queue.append((nr,nc))
        return region

